args => {
  const [isVisible, setIsVisible] = useState(args.isVisible);
  useEffect(() => {
    let timer;
    if (args.position === 'fixed' && isVisible) {
      timer = setTimeout(() => {
        setIsVisible(false);
      }, 2000);
    } else if (args.position !== 'fixed') {
      setIsVisible(true);
    }
    return () => clearTimeout(timer);
  }, [args.position, isVisible]);
  return <div style={{
    width: '100%',
    height: '200px'
  }}>\r
      <Loading {...args} isVisible={isVisible} />\r
    </div>;
}

